// import Util from '@baifendian/adhere-util';
import { ERROR_MESSAGE, OK_MESSAGE } from '../Constant';
import Context from '../Context';
import Request from '../Request';
import Response from '../Response';
import Compose from './compose';
/**
 * Server
 * @class Server
 * @classdesc iframe postMessage 服务端
 */
class Server {
    // 白名单
    whitelist = [];
    // SourceWindow
    source;
    // SourceOrigin
    sourceOrigin;
    // 中间件队列
    middleWareQueue = [];
    constructor(whitelist = [], source, sourceOrigin) {
        this.whitelist = whitelist;
        this.source = source;
        this.sourceOrigin = sourceOrigin;
        this.onMessage = this.onMessage.bind(this);
    }
    /**
     * onMessage
     * @description 接收到消息
     * @param evt
     */
    onMessage(evt) {
        try {
            const data = JSON.parse(evt.data);
            // 略掉不是白名单中的请求，或没有request的请求
            if (!this.whitelist.includes(evt.origin) ||
                !evt.source ||
                data === null ||
                data === undefined ||
                data === '' ||
                typeof data !== 'object' ||
                !('requestId' in data) ||
                data.requestId === null ||
                data.requestId === undefined ||
                data.requestId === '') {
                return;
            }
            if (data.type === 'response') {
                return;
            }
            this.service(evt, data);
        }
        catch (e) {
            console.warn(e);
        }
    }
    /**
     * middleWareQueueReduce
     * @description 对中间件进行迭代
     * @private
     * @param ctx 上下文对象
     */
    middleWareQueueReduce(ctx) {
        const middleWareCompose = Compose(this.middleWareQueue);
        return middleWareCompose(ctx);
    }
    /**
     * service
     * @description 具体的请求处理
     * @param {MessageEvent} evt
     * @param {any} data
     * @private
     */
    service(evt, data) {
        // 设置request的statusCode和statusMessage
        const request = new Request(data);
        request.setRequestId(data.requestId);
        request.setStatusCode(200);
        request.setStatusMessage(OK_MESSAGE);
        // 如果中间件为空
        if (!this.middleWareQueue.length) {
            return;
        }
        // 迭代middleWareQueue
        // 如果中间件队列不为空则创建上下文对象
        const context = new Context({
            request,
            response: new Response({
                requestId: request.getRequestId(),
                statusCode: 0,
                stateMessage: ERROR_MESSAGE,
                headers: {
                    pathname: request.getPathname(),
                    date: new Date().toString(),
                    origin: this.sourceOrigin,
                    referer: this.source instanceof Window ? this.source.location.href : '',
                },
                body: null,
                type: 'response',
            }),
        });
        this.middleWareQueueReduce(context).then(() => {
            // 返回响应
            try {
                // @ts-ignore
                evt?.source?.postMessage?.(JSON.stringify(context.response), evt.origin);
            }
            catch (e) {
                console.log(e);
            }
        });
    }
    /**
     * start
     * @description 启动服务
     */
    start() {
        return new Promise((resolve) => {
            this.source.addEventListener('message', this.onMessage);
            resolve();
        });
    }
    /**
     * close
     * @description 关闭服务
     */
    close() {
        return new Promise((resolve) => {
            this.source.removeEventListener('message', this.onMessage);
            resolve();
        });
    }
    /**
     * use
     * @description 添加中间件
     * @param middleWare
     */
    use(middleWare) {
        if (Array.isArray(middleWare)) {
            this.middleWareQueue.push(...middleWare);
        }
        else {
            this.middleWareQueue.push(middleWare);
        }
        return this;
    }
}
export default Server;
